import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { format } from "prettier";
import { sizing } from "../packages/tokens/src/sizing.ts";
import {
  containerWidths,
  breakpoints,
  responsiveGutters,
  minWidth,
} from "../packages/tokens/src/layout.ts";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const header =
  "/* Generated by scripts/generate-sizing-layout.mjs. Do not edit. */\n";
const rem = (px) => `${px / 16}rem`;
const declarations = (entries) =>
  entries.map(([name, value]) => `--dixy-${name}: ${value};`).join("\n");

const sizingCss = `${header}@layer dixy.tokens {
  :root {
    ${declarations(
      Object.entries(sizing).flatMap(([family, tokens]) =>
        Object.entries(tokens).map(([token, px]) => [
          `size-${family}-${token}`,
          family === "target" ? `max(${px}px, ${rem(px)})` : rem(px),
        ]),
      ),
    )}
    --dixy-interaction-target: var(--dixy-size-target-minimum);
  }
  /* Retain the existing control-height override contract at theme boundaries. */
  :root, .dixy-theme {
    ${declarations(Object.keys(sizing.control).map((token) => [`height-${token}`, `var(--dixy-size-control-${token})`]))}
  }
}\n`;

const layoutCss = `${header}@layer dixy.tokens {
  :root {
    ${declarations(Object.entries(containerWidths).map(([name, px]) => [`container-${name}`, rem(px)]))}
    ${declarations(Object.entries(breakpoints).map(([name, px]) => [`breakpoint-${name}`, rem(px)]))}
    --dixy-layout-gutter: var(--dixy-space-${responsiveGutters.base});
  }
  ${Object.entries(responsiveGutters)
    .filter(([name]) => name !== "base")
    .map(
      ([name, token]) => `@media ${minWidth(name)} {
    :root { --dixy-layout-gutter: var(--dixy-space-${token}); }
  }`,
    )
    .join("\n")}
}\n`;

const componentCss = `${header}@layer dixy.components {
  ${Object.keys(containerWidths)
    .map(
      (token) =>
        `.dixy-container[data-size="${token}"] { max-inline-size: var(--dixy-container-${token}); }`,
    )
    .join("\n")}
}\n`;
const outputs = {
  "packages/tokens/src/sizing.css": sizingCss,
  "packages/tokens/src/layout.css": layoutCss,
  "packages/react/src/tokens/container-sizing.css": componentCss,
};
if (process.argv.includes("--dist")) {
  outputs["packages/tokens/dist/sizing.css"] = sizingCss;
  outputs["packages/tokens/dist/layout.css"] = layoutCss;
}
for (const [file, raw] of Object.entries(outputs)) {
  const content = await format(raw, { parser: "css" });
  const target = path.join(root, file);
  const current = fs.existsSync(target) ? fs.readFileSync(target, "utf8") : "";
  if (process.argv.includes("--check")) {
    if (current !== content)
      throw new Error(`${file} is stale. Run pnpm tokens:generate.`);
  } else if (current !== content) {
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, content);
  }
}
console.log(
  process.argv.includes("--check")
    ? "Sizing/layout outputs match their canonical contracts."
    : "Sizing/layout CSS generated from token contracts.",
);
